/* =========================================================
   SSJ · Journey selector · Global Styles v1 (prueba)
   Pegar como bloque NUEVO en Global Styles (para poder revertir).
   Todo va con prefijo .ssj para no chocar con nada existente.
   ========================================================= */


/* ---------------------------------------------------------
   1. TOKENS Y BASE
   --------------------------------------------------------- */
.ssj {
  --ssj-midnight: #370C3B;
  --ssj-deep: #2a0a2e;
  --ssj-snow: #FCFAF7;
  --ssj-dusk: #F14283;
  --ssj-sunrise: #FA6B4C;
  --ssj-yellow: #FFDE68;
  --ssj-body: #5d4a6c;
  --ssj-grad: linear-gradient(149.92deg, #FF7E47, #FA6746, #FA4B82, #F582E2);
  font-family: inherit;
  box-sizing: border-box;
}
.ssj *, .ssj *::before, .ssj *::after { box-sizing: border-box; }

.ssj__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 64px 24px;
}

.ssj--dark {
  background:
    radial-gradient(ellipse at 50% 55%, rgba(241, 66, 131, .35), transparent 60%),
    var(--ssj-deep);
  color: #fff;
  text-align: center;
}
.ssj--light {
  background: var(--ssj-snow);
  color: var(--ssj-midnight);
}


/* ---------------------------------------------------------
   2. TITULARES, PILL DE PASO, SUBTÍTULO
   --------------------------------------------------------- */
.ssj__step {
  display: inline-block;
  padding: 6px 16px;
  border: 1px solid var(--ssj-dusk);
  border-radius: 999px;
  color: var(--ssj-dusk);
  font-size: 14px;
  font-weight: 600;
}
.ssj__title {
  margin: 24px 0 16px;
  font-size: clamp(36px, 6vw, 72px);
  line-height: 1;
  font-weight: 500;
  text-transform: uppercase;
  color: inherit;
}
.ssj__title em {
  display: block;
  font-style: normal;
  color: var(--ssj-dusk);
}
.ssj__sub {
  max-width: 620px;
  margin: 0 auto;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.4;
}


/* ---------------------------------------------------------
   3. REJILLA Y TARJETAS (dark)
   --------------------------------------------------------- */
.ssj__grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
  max-width: 760px;
  margin: 40px auto 0;
}

.ssj-card {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 24px;
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
  background: rgba(255, 255, 255, .06);
  border: 1px solid rgba(255, 255, 255, .18);
  border-radius: 24px;
  transition: border-color .2s, background .2s, transform .2s;
}
.ssj-card:hover {
  border-color: rgba(255, 255, 255, .4);
  transform: translateY(-2px);
}
.ssj-card:focus-visible {
  outline: 2px solid var(--ssj-yellow);
  outline-offset: 2px;
}
.ssj-card__title {
  font-size: 32px;
  line-height: 1;
  text-transform: uppercase;
  font-weight: 500;
}
.ssj-card--sm .ssj-card__title {
  font-size: 18px;
  text-transform: none;
  font-weight: 600;
}
.ssj-card__text {
  font-size: 15px;
  line-height: 1.45;
  opacity: .85;
}

/* Estado seleccionado (solo capas y verticales; persona avanza directo) */
.ssj-card[data-ss-layer].is-selected,
.ssj-card[data-ss-vertical].is-selected {
  border-color: var(--ssj-yellow);
  background: rgba(255, 255, 255, .14);
}
.ssj-card[data-ss-layer].is-selected::after,
.ssj-card[data-ss-vertical].is-selected::after {
  content: "\2713";
  position: absolute;
  top: 16px;
  right: 16px;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--ssj-yellow);
  color: var(--ssj-midnight);
  font-size: 14px;
  font-weight: 700;
  line-height: 24px;
  text-align: center;
}

/* Punto de color y tags de las verticales */
.ssj-dot {
  display: inline-block;
  width: 12px;
  height: 12px;
  margin-right: 8px;
  border-radius: 50%;
  background: var(--ssj-dusk);
}
.ssj-dot--purple { background: #7b2d8e; }
.ssj-dot--pink   { background: var(--ssj-dusk); }
.ssj-dot--yellow { background: var(--ssj-yellow); }
.ssj-dot--orange { background: var(--ssj-sunrise); }

.ssj-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.ssj-tag {
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .12);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
}


/* ---------------------------------------------------------
   4. BOTONES Y ENLACES
   --------------------------------------------------------- */
.ssj__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  margin-top: 40px;
}
.ssj-btn {
  display: inline-block;
  padding: 12px 28px;
  font: inherit;
  font-weight: 600;
  color: inherit;
  text-decoration: none;
  cursor: pointer;
  background: transparent;
  border: 1.5px solid currentColor;
  border-radius: 999px;
  transition: opacity .2s;
}
.ssj-btn:hover { opacity: .8; }
.ssj-btn--primary {
  border: 0;
  background: var(--ssj-grad);
  color: #fff;
}
.ssj-btn--sm {
  padding: 8px 18px;
  font-size: 14px;
}
.ssj-link {
  display: inline-block;
  margin-top: 32px;
  color: inherit;
  text-decoration: underline;
}


/* ---------------------------------------------------------
   5. RESULTADOS · HERO
   --------------------------------------------------------- */
.ssj--hero .ssj__inner { padding: 48px 24px; }
.ssj--hero .ssj__title { font-size: clamp(32px, 5vw, 56px); }
.ssj--hero .ssj__title em { text-transform: uppercase; }
.ssj--hero .ssj__actions { margin-top: 24px; }


/* ---------------------------------------------------------
   6. RESULTADOS · CAPAS (Discover / Connect / Lead)
   --------------------------------------------------------- */
.ssj-layer .ssj__inner {
  max-width: 700px;
  padding: 32px 24px;
}
.ssj-layer__head {
  display: flex;
  align-items: baseline;
  gap: 16px;
  padding-top: 16px;
  border-top: 1px solid rgba(55, 12, 59, .2);
}
.ssj-layer__num {
  font-size: 12px;
  color: var(--ssj-sunrise);
}
.ssj-layer__title {
  margin: 0;
  font-size: 40px;
  line-height: 1;
  font-weight: 500;
  text-transform: uppercase;
  color: var(--ssj-midnight);
}
.ssj-badge {
  margin-left: auto;
  padding: 3px 10px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.ssj-layer--discover .ssj-badge { background: #fff2c2; color: #8a6a00; }
.ssj-layer--connect  .ssj-badge { background: #ffe1da; color: #b8391c; }
.ssj-layer--lead     .ssj-badge { background: #ffd9e8; color: #b0195a; }

.ssj-layer__sub {
  margin: 8px 0 0;
  font-size: 14px;
  color: var(--ssj-body);
}
.ssj-items {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
  margin: 16px 0 0;
  padding: 0;
  list-style: none;
}
.ssj-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 14px 18px;
  background: #fff;
  border: 1px solid rgba(55, 12, 59, .15);
  border-radius: 12px;
}
.ssj-item strong { font-size: 18px; font-weight: 500; }
.ssj-item span   { font-size: 13px; color: var(--ssj-body); }


/* ---------------------------------------------------------
   7. RESULTADOS · VERTICALES
   --------------------------------------------------------- */
.ssj-vertical .ssj__inner {
  max-width: 700px;
  padding: 40px 24px;
}
.ssj-kicker {
  display: inline-flex;
  align-items: center;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: .04em;
  text-transform: uppercase;
}
.ssj-vertical__title {
  margin: 8px 0 12px;
  font-size: 36px;
  line-height: 1;
  font-weight: 500;
  text-transform: uppercase;
  color: var(--ssj-midnight);
}
.ssj-vertical__text {
  margin: 0 0 20px;
  font-size: 15px;
  line-height: 1.5;
  color: var(--ssj-body);
}


/* ---------------------------------------------------------
   8. RESPONSIVE
   --------------------------------------------------------- */
@media (max-width: 640px) {
  .ssj__grid,
  .ssj-items { grid-template-columns: 1fr; }
  .ssj__inner { padding: 48px 16px; }
}

/* @inwink-mcp style key=footer-mobile-accordion v=1 — géré par l'assistant inwink (MCP CMS) : ne pas éditer à la main, il serait alors ignoré par l'assistant */
/* Footer: acordeon solo en movil (<=600px), activo solo si el script puso html.ss-acc-on */
@media screen and (max-width: 600px) {
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs { row-gap: 0; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :first-child { margin-bottom: 24px; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(n+2):nth-child(-n+5) { border-bottom: 1px solid rgba(55, 12, 59, 0.16); }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(2) { border-top: 1px solid rgba(55, 12, 59, 0.16); }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(6) { margin-top: 24px; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(n+2):nth-child(-n+5) .bloc-header { position: relative; min-height: 56px; margin: 0; padding-right: 40px; cursor: pointer; -webkit-tap-highlight-color: transparent; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(n+2):nth-child(-n+5) .bloc-header:focus-visible { outline: 2px solid #F14283; outline-offset: 2px; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(n+2):nth-child(-n+5) .bloc-header::after { content: ""; position: absolute; right: 8px; top: 50%; width: 8px; height: 8px; border-right: 1.5px solid #370C3B; border-bottom: 1.5px solid #370C3B; transform: translateY(-70%) rotate(45deg); transition: transform 0.2s ease; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > .is-open .bloc-header::after { transform: translateY(-30%) rotate(-135deg); }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(n+2):nth-child(-n+5) .bloc-content { display: none; padding-bottom: 16px; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > .is-open .bloc-content { display: block; }
  html.ss-acc-on #bl-027bea74-4728-42e0-a43e-35c5ec121bfe .dynamicbloc-wrapper-contentblocs > :nth-child(n+2):nth-child(-n+5) .contentpagelink { display: flex; align-items: center; min-height: 40px; }
}

/* =========================================================
   South Summit · Cabecera (nav) · Global Styles · v6
   Sustituye al bloque anterior en BO > Webmaster > Estilos globales (CSS).
   Selectores reales del DevTools: #appheadermenu, .menuitem.level-1,
   a.iconlink.level-1, div.sub-menu-button.
   ========================================================= */

/* Entradas principales en mayúsculas, 14px, como el prototipo (.menu) */
#approot #appheadermenu .menuitem.level-1 a.iconlink.level-1,
#approot #appheadermenu .menuitem.level-1 a.iconlink.level-1 span {
  text-transform: uppercase;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

/* Más aire entre entradas (prototipo: 22px entre elementos) */
#approot #appheadermenu .menuitem.level-1 {
  margin-left: 11px;
  margin-right: 11px;
}

/* Flecha de desplegable: sin círculo, solo la flecha en morado (color del texto) */
#approot #appheadermenu .sub-menu-button,
#approot #appheadermenu .sub-menu-button * {
  background: transparent;
  background-color: transparent;
  background-image: none;
  border: 0;
  box-shadow: none;
  color: #370C3B;
}

#approot #appheadermenu .sub-menu-button {
  margin-left: 4px;
}

/* Barra un poco más alta (prototipo ~70px): relleno arriba/abajo, SIN altura fija
   para no recortar los desplegables (.sub-menu-modal-content) */
#approot .headercontent.withheaderitems {
  padding-top: 6px;
  padding-bottom: 6px;
  box-sizing: content-box;
  overflow: visible;
}

/* Sign in (última entrada) a la derecha; el resto sigue centrado */
#approot #appheadermenu {
  position: relative;
}

#approot #appheadermenu .menuitem.level-1:last-child {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  margin: 0;
}

/* ---------------------------------------------------------
   Desplegables (Events / Ways to Engage) como el prototipo (.ddm)
   inwink no pinta la descripción de las entradas: el subtítulo se
   añade aquí, por el aria-label real de cada enlace.
   Para cambiar una fecha, edita su línea "content".
   --------------------------------------------------------- */
#approot .sub-menu-items .menuitem.level-2 a.submenu.level-2 {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 2px;
  padding: 12px 16px;
  border-radius: 12px;
  font-size: 16px;
  text-transform: none;
}

#approot .sub-menu-items .menuitem.level-2 a.submenu.level-2:hover {
  background: #F4EDF3;
}

#approot .sub-menu-items .menuitem.level-2 a.submenu.level-2::after {
  display: block;
  font-size: 13px;
  font-weight: 400;
  line-height: 1.4;
  color: #6B5670;
  text-transform: none;
  letter-spacing: 0;
}

/* Events */
#approot .sub-menu-items a.submenu.level-2[aria-label="Madrid"]::after { content: "June 2–4 2027"; }
#approot .sub-menu-items a.submenu.level-2[aria-label="Brazil"]::after { content: "[Date]"; }
#approot .sub-menu-items a.submenu.level-2[aria-label="Bilbao"]::after { content: "[Date]"; }
#approot .sub-menu-items a.submenu.level-2[aria-label="International Events"]::after { content: "Series across cities"; }

/* Ways to Engage */
#approot .sub-menu-items a.submenu.level-2[aria-label="Discover"]::after { content: "Get the picture"; }
#approot .sub-menu-items a.submenu.level-2[aria-label="Connect"]::after { content: "Find what is relevant"; }
#approot .sub-menu-items a.submenu.level-2[aria-label="Lead"]::after { content: "Go deeper"; }

/* ---------------------------------------------------------
   Panel del desplegable como el prototipo (.ddm):
   esquinas redondeadas, sombra suave y animación al abrir.
   Selector real: div.sub-menu-modal-content (con .hidden cuando está cerrado).
   --------------------------------------------------------- */
#approot .sub-menu-modal-content {
  border-radius: 18px;
  padding: 8px;
  min-width: 250px;
  box-shadow: 0 18px 48px rgba(35, 6, 46, 0.18);
  overflow: hidden;
  transform-origin: top center;
}

#approot .sub-menu-modal-content:not(.hidden) {
  animation: ss-dropdown-in 180ms ease-out;
}

@keyframes ss-dropdown-in {
  from { opacity: 0; transform: translateY(-6px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

/* Accesibilidad: sin animación si el usuario lo tiene desactivado en su sistema */
@media (prefers-reduced-motion: reduce) {
  #approot .sub-menu-modal-content:not(.hidden) {
    animation: none;
  }
}

